                        style: theme.textTheme.bodySmall?.copyWith(
                          color: theme.colorScheme.error,
                        ),
                      ),
                    ),
                  ],
                ),
              ],
              if (network || allowedCommands.isNotEmpty) ...[
                const SizedBox(height: 12),
                if (network)
