Map<String, Uint8List> folder({
  String id = 'fa-agents',
  String name = 'FA Agents',
  Map<String, Object?> extra = const {},
  String root = '',
}) {
  final manifest = jsonEncode({
    'id': id,
    'name': name,
    'version': '0.3.0',
    ...extra,
  });
