    if (root.isEmpty) 'manifest.json': utf8.encode(manifest),
    if (root.isEmpty) 'widget.js': utf8.encode('jsr.render(null);'),
  };
}

Map<String, Map<String, String>> castMeta(Object? decoded) => {
